type Modal = 'loan' | 'customer' | 'payment' | 'topup' | 'exception' | 'settings' | 'profile' | 'access' | 'assignment' | 'reminder' | 'topupDecision' | null;



type NavItem = { label: string; icon: typeof LayoutDashboard; badge?: string };

const adminNav: NavItem[] = [
  { label: 'Overview', icon: LayoutDashboard }, { label: 'Customers', icon: UsersRound },
  { label: 'Loans', icon: WalletCards }, { label: 'Collections', icon: HandCoins },
  { label: 'Agents', icon: UserRound }, { label: 'Reports', icon: FileText }, { label: 'Reminders', icon: MessageCircle },
];

const roleNav: Record<Role, NavItem[]> = {
  admin: adminNav,
  agent: [{ label: 'My Dashboard', icon: LayoutDashboard }, { label: 'Assigned customers', icon: UsersRound }, { label: 'Collections', icon: HandCoins }, { label: 'My reports', icon: FileText }, { label: 'Reminders', icon: MessageCircle }],
  customer: [{ label: 'My loan', icon: LayoutDashboard }, { label: 'Repayments', icon: HandCoins }, { label: 'Top-up requests', icon: WalletCards }, { label: 'My reports', icon: FileText }],
};

const roleName = { admin: 'Super Admin', agent: 'Collection Agent', customer: 'Customer' };
const customerIdByName:Record<string,string>={'Arjun Mehta':'customer-arjun','Priya Sharma':'customer-priya','Ravi Kumar':'customer-ravi','Neha Patel':'customer-neha'};
async function postData(payload:Record<string,unknown>) { const response=await fetch('/api/data',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload),signal:AbortSignal.timeout(15000)}); if(!response.ok) { throw new Error((await response.json()).error||'Database update failed'); } return response.json(); }
async function getData() { const response=await fetch('/api/data',{signal:AbortSignal.timeout(15000)}); if(!response.ok) { throw new Error((await response.json()).error||'Could not load finance data'); } return response.json(); }
const money=(value:number)=>'₹'+Number(value||0).toLocaleString('en-IN');
const refreshData=()=>window.dispatchEvent(new Event('fundflow-data'));


function LoanCountBadge() {
  const [count,setCount]=useState<number|null>(null);
  useEffect(()=>{
    let mounted=true,latest=0;
    const load=async()=>{const version=++latest;try{const data=await getData();const value=Array.isArray(data.loans)?data.loans.length:null;if(mounted&&version===latest)setCount(value)}catch{if(mounted&&version===latest)setCount(null)}};
    void load();window.addEventListener('fundflow-data',load);window.addEventListener('focus',load);
    return()=>{mounted=false;window.removeEventListener('fundflow-data',load);window.removeEventListener('focus',load)};
  },[]);
  return <span aria-label={count===null?'Loan count unavailable or loading':`${count} total loans`} title="Total loan records, including settled and foreclosed loans" className="ml-auto min-w-6 rounded-full bg-[#d9ff54] px-2 py-0.5 text-center text-[10px] font-bold tabular-nums text-[#16372b]">{count===null?'—':count.toLocaleString('en-IN')}</span>;
}
export default function Home() {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [collectionsOpen, setCollectionsOpen] = useState(false);
  const [active, setActive] = useState('Overview');
  const [session, setSession] = useState<SessionUser|null|undefined>(undefined);
  const [modal, setModal] = useState<Modal>(null);
  const [toast, setToast] = useState('');
  const [period, setPeriod] = useState('Today');
  const [assignments, setAssignments] = useState<Record<string,string>>({});
  const [selectedCustomer, setSelectedCustomer] = useState('Arjun Mehta');
  const [selectedCustomerId, setSelectedCustomerId] = useState('customer-arjun');
  const [selectedAgent, setSelectedAgent] = useState('Deepak Singh');
  const [reminderChannel, setReminderChannel] = useState<'SMS'|'WhatsApp'>('SMS');
  useEffect(()=>{const show=()=>{setModal(null);setActive('Reminders')};window.addEventListener('fundflow-reminders',show);return()=>window.removeEventListener('fundflow-reminders',show)},[]);
  const [topupDecision, setTopupDecision] = useState<'approve'|'decline'>('approve');
  const [topupStatus, setTopupStatus] = useState<'Pending'|'Approved'|'Declined'>('Pending');
  const [brandVersion,setBrandVersion]=useState(Date.now());
  const [customLogo,setCustomLogo]=useState(false);
  const role: Role = session?.role || 'customer';
  const nav = roleNav[role];
  const finish = (message: string) => { setModal(null); setToast(message); window.setTimeout(() => setToast(''), 2800); };
  useEffect(()=>{const loadBrand=async()=>{const version=Date.now();setBrandVersion(version);try{const logo=await fetch('/api/branding/logo',{cache:'no-store'});setCustomLogo(logo.ok);}catch{setCustomLogo(false);}try{const favicon=await fetch('/api/branding/favicon',{cache:'no-store'});if(favicon.ok){let link=document.querySelector('link[rel="icon"]') as HTMLLinkElement|null;if(!link){link=document.createElement('link');link.rel='icon';document.head.appendChild(link);}link.href='/api/branding/favicon?v='+version;}}catch{}};loadBrand();window.addEventListener('fundflow-brand',loadBrand);return()=>window.removeEventListener('fundflow-brand',loadBrand);},[]);  useEffect(()=>{fetch('/api/auth/session',{cache:'no-store'}).then(async response=>response.ok?(await response.json()).user:null).then(user=>{setSession(user);if(user)setActive(roleNav[user.role as Role][0].label)}).catch(()=>setSession(null));},[]);
  useEffect(()=>{
    if(!session||session.role==='customer')return;
    const record=(event:MouseEvent)=>{
      const button=(event.target as HTMLElement)?.closest('button');
      if(!button)return;
      const label=(button.getAttribute('aria-label')||button.textContent||'').trim().slice(0,100);
      if(!label)return;
      void fetch('/api/activity',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({activity:'Clicked '+label}),keepalive:true}).catch(()=>{});
    };
    document.addEventListener('click',record,true);
    return()=>document.removeEventListener('click',record,true);
  },[session]);
  if(session===undefined)return <main className="grid min-h-screen place-items-center bg-[#eef4f1] text-sm font-semibold text-[#315347]">Loading secure portal...</main>;
  if(!session)return <LoginPage onLogin={(user)=>{setSession(user);setActive(roleNav[user.role][0].label)}}/>;
  return <main className="min-h-screen bg-[#f3f7f5] text-[#15261f]">
    <aside className={`admin-sidebar-scroll overflow-hidden fixed inset-y-0 left-0 z-40 flex w-[250px] flex-col bg-[#0c3327] text-white transition-transform lg:translate-x-0 ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
      <div className="flex h-[76px] items-Messages justify-between border-b border-white/10 px-6"><div className="flex items-center gap-3"><img src={customLogo?"/api/branding/logo?v="+brandVersion:"/rmv-finance-logo.jpeg"} alt="RMV Finance logo" width={44} height={44} className="size-11 shrink-0 rounded-xl object-contain"/><div><div className="text-[17px] font-bold tracking-tight">RMV Finance</div><div className="text-[10px] font-medium uppercase tracking-[.16em] text-white/50"></div></div></div><button className="lg:hidden" onClick={() => setSidebarOpen(false)} aria-label="Close menu"><X className="size-5" /></button></div>
      <div className={`min-h-0 flex-1 overflow-y-auto px-4 py-5 ${role==='admin'?'admin-sidebar-scroll':''}`}><p className="px-3 pb-2 text-[10px] font-semibold uppercase tracking-[.17em] text-white/40">Workspace</p><nav className="space-y-1">{nav.map((item) => <div key={item.label}><button onClick={() => {if(role==='admin'&&item.label==='Collections'){setCollectionsOpen(value=>!value);if(!collectionsOpen)setActive('Collections');return;}setActive(item.label);setSidebarOpen(false)}} aria-expanded={role==='admin'&&item.label==='Collections'?collectionsOpen:undefined} aria-controls={role==='admin'&&item.label==='Collections'?'collections-submenu':undefined} aria-current={active===item.label?'page':undefined} className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm transition ${active === item.label || (role==='admin'&&item.label==='Collections'&&collectionViews.some(view=>view.label===active)) ? 'bg-white text-[#12372b] shadow-sm' : 'text-white/70 hover:bg-white/8 hover:text-white'}`}><item.icon className="size-4" /><span>{item.label}</span>{role==='admin'&&item.label==='Loans'&&<LoanCountBadge key={session.id}/>}{role==='admin'&&item.label==='Collections'&&<ChevronDown aria-hidden={true} className={'ml-auto size-4 transition-transform '+(collectionsOpen?'rotate-180':'')}/>}{item.badge && <span className="ml-auto rounded-full bg-[#d9ff54] px-2 py-0.5 text-[10px] font-bold text-[#16372b]">{item.badge}</span>}</button>{role==='admin'&&item.label==='Collections'&&collectionsOpen&&<div id="collections-submenu" aria-label="Collection frequency" className="ml-5 mt-1 space-y-1 border-l border-white/20 pl-3">{collectionViews.map(view=><button key={view.frequency} onClick={()=>{setActive(view.label);setSidebarOpen(false)}} aria-current={active===view.label?'page':undefined} className={`block w-full rounded-lg px-2 py-2 text-left text-xs transition ${active===view.label?'bg-white/15 font-semibold text-[#d9ff54]':'text-white/65 hover:bg-white/8 hover:text-white'}`}>{view.label}</button>)}</div>}</div>)}</nav></div>
      <div className="mt-auto p-4">{role==='admin'&&<button onClick={()=>setModal('settings')} className="mb-3 flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm text-white/65 hover:bg-white/8"><Settings className="size-4"/> Settings</button>}<button type="button" onClick={()=>role==='admin'&&setModal('profile')} className="w-full rounded-2xl border border-white/10 bg-white/7 p-3 text-left transition hover:bg-white/10"><div className="flex items-center gap-3"><div className="grid size-9 place-items-center rounded-full bg-[#d9ff54] text-xs font-bold text-[#183c2e]">{session.name.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase()}</div><div className="min-w-0"><p className="truncate text-sm font-semibold">{session.name}</p><p className="text-xs text-white/45">{role==='admin'?'Profile & password':roleName[role]}</p></div>{role==='admin'?<Pencil className="ml-auto size-4 text-white/50"/>:<ChevronDown className="ml-auto size-4 text-white/50" />}</div></button></div>
    </aside>
    <div className="lg:pl-[250px]">
      <header className="sticky top-0 z-30 flex h-[76px] items-center gap-3 border-b border-[#dce6e1] bg-white/90 px-5 backdrop-blur-xl lg:px-8"><button className="lg:hidden" onClick={() => setSidebarOpen(true)} aria-label="Open menu"><Menu className="size-5" /></button><div className="relative hidden max-w-sm flex-1 md:block"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-[#789087]" /><input className="h-10 w-full rounded-xl border border-[#dce5e0] bg-[#f7faf8] pl-10 pr-4 text-sm outline-none focus:border-[#1e6e50]" placeholder="Search records..." /></div><div className="ml-auto flex items-center gap-2">{role!=='customer'&&<PwaInstall/>}<div className="hidden rounded-xl border border-[#d7e2dd] bg-white px-3 py-2 text-xs font-semibold sm:block">{roleName[role]}</div><Notifications key={session.id} userId={session.id} role={role} navigate={setActive}/><button onClick={async()=>{await fetch('/api/auth/logout',{method:'POST'});setSession(null)}} className="grid size-9 place-items-center rounded-xl border border-[#dce5e0] bg-white text-[#6d8178]" aria-label="Sign out"><LogOut className="size-4"/></button><Button onClick={() => setModal(role === 'admin' ? 'loan' : role === 'agent' ? 'payment' : 'topup')} className="h-10 rounded-xl bg-[#153d30] px-4 hover:bg-[#205a46]"><Plus /> <span className="hidden sm:inline">{role === 'admin' ? 'New loan' : role === 'agent' ? 'Record payment' : 'Request top-up'}</span></Button></div></header>
      <section className="p-5 lg:p-8">{active === 'Reminders' ? <ReminderPanel /> : role !== 'admin' ? <RolePortal role={role} active={active} period={period} setPeriod={setPeriod} open={setModal} notify={finish} /> : active !== 'Overview' ? <AdminSection active={active} period={period} setPeriod={setPeriod} open={setModal} notify={finish} assignments={assignments} assignCustomer={(name,id) => { setSelectedCustomer(name); setSelectedCustomerId(id||customerIdByName[name]||''); setModal('assignment'); }} manageAgent={(name) => { setSelectedAgent(name); setModal('access'); }} /> : <Dashboard name={session.name} period={period} setPeriod={setPeriod} navigate={setActive}/>}
      </section>
    </div>{sidebarOpen && <button aria-label="Close navigation" className="fixed inset-0 z-30 bg-black/35 lg:hidden" onClick={() => setSidebarOpen(false)} />}
    {modal === 'profile' ? <ProfileDialog session={session} close={()=>setModal(null)} updated={(user)=>{setSession(user);finish('Administrator profile updated')}}/> : modal === 'settings' || modal === 'access' || modal === 'assignment' ? <AdminToolDialog modal={modal} close={() => setModal(null)} finish={finish} selectedCustomer={selectedCustomer} selectedCustomerId={selectedCustomerId} selectedAgent={selectedAgent} saveAssignment={async(agentId,agentName) => { try { await postData({action:'assign_customer',customer_id:selectedCustomerId,agent_id:agentId}); setAssignments((current) => ({...current, [selectedCustomer]: agentName})); refreshData(); finish(selectedCustomer + ' assigned to ' + agentName); } catch(error) { finish(error instanceof Error?error.message:'Assignment failed'); } }} /> : modal === 'reminder' ? <ReminderDialog channel={reminderChannel} close={()=>setModal(null)} finish={finish}/> : modal === 'topupDecision' ? <TopupDecisionDialog decision={topupDecision} close={()=>setModal(null)} finish={(message)=>{setTopupStatus(topupDecision === 'approve' ? 'Approved' : 'Declined');finish(message)}}/> : <ActionDialog paymentFrequency={role==='admin'?collectionViews.find(view=>view.label===active)?.frequency:undefined} modal={modal} close={() => setModal(null)} finish={finish} />}
    {toast && <div role="status" className="fixed bottom-5 right-5 z-[80] flex items-center gap-3 rounded-xl bg-[#123b2d] px-4 py-3 text-sm font-semibold text-white shadow-2xl"><span className="grid size-6 place-items-center rounded-full bg-[#d9ff54] text-[#153d30]"><Check className="size-4" /></span>{toast}</div>}
  </main>;
}

function LoginPage({onLogin}:{onLogin:(user:SessionUser)=>void}) {
  const [username,setUsername]=useState('');const [password,setPassword]=useState('');const [showPassword,setShowPassword]=useState(false);const [loading,setLoading]=useState(false);const [error,setError]=useState('');
  const submit=async(e:React.FormEvent)=>{e.preventDefault();if(loading)return;setLoading(true);setError('');try{const response=await fetch('/api/auth/login',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({username,password}),signal:AbortSignal.timeout(20000)});if(!response.headers.get('content-type')?.includes('application/json'))throw new Error('The server is running an outdated login gateway. Deploy the latest RMV Finance app.');const data=await response.json();if(!response.ok)throw new Error(data.error||'Sign in failed');onLogin(data.user);}catch(error){setError(error instanceof Error&&['TimeoutError','AbortError'].includes(error.name)?'Sign-in timed out. Please try again.':error instanceof Error?error.message:'Unable to reach the login server. Please try again.');}finally{setLoading(false)}};
  return <main className="grid min-h-screen place-items-center bg-[#eaf1ed] p-5"><div className="grid w-full max-w-4xl overflow-hidden rounded-[28px] border border-[#d2dfd8] bg-white shadow-[0_30px_80px_rgba(12,51,39,.16)] md:grid-cols-[1.05fr_.95fr]"><section className="hidden bg-[#0c3327] p-10 text-white md:flex md:flex-col"><div className="flex items-center gap-3"><img src="/rmv-finance-logo.jpeg" alt="RMV Finance logo" width={56} height={56} className="size-14 shrink-0 rounded-xl object-contain"/><div><b className="text-xl">RMV Finance</b><p className="text-xs uppercase tracking-[.18em] text-white/50">Finance Lending Platform</p></div></div><div className="mt-auto flex items-center gap-3"><LockKeyhole aria-hidden="true" className="size-8 shrink-0 text-[#d9ff54]"/>
  <h1 className="whitespace-nowrap text-2xl font-bold tracking-tight">Secure operations.</h1>
  {/*<p className="mt-3 max-w-sm text-sm leading-6 text-white/60">Super admins manage customers and loans. Collection agents see only their assigned customers. Customer portal login is temporarily paused.</p>*/}
  </div></section><form onSubmit={submit} className="p-7 sm:p-10"><p className="text-xs font-bold uppercase tracking-[.16em] text-[#688078]">Account access</p><h2 className="mt-2 text-3xl font-bold tracking-tight">Sign in to RMV Finance</h2><p className="mt-2 text-sm text-[#71857d]">Enter the credentials below.</p><div className="mt-8 grid gap-4"><Field label="Username"><Input autoComplete="username" value={username} onChange={(e)=>setUsername(e.target.value)} placeholder="Enter username"/></Field><Field label="Password"><div className="relative"><Input autoComplete="current-password" type={showPassword?'text':'password'} value={password} onChange={(e)=>setPassword(e.target.value)} placeholder="Enter password" className="pr-12"/><button type="button" onClick={()=>setShowPassword(!showPassword)} className="absolute right-3 top-1/2 -translate-y-1/2 text-xs font-bold text-[#28664f]">{showPassword?'Hide':'Show'}</button></div></Field>{error&&<div className="rounded-xl bg-[#fff0ed] p-3 text-sm font-semibold text-[#a24432]">{error}</div>}<Button type="submit" disabled={loading||!username||!password} className="mt-2 h-11 w-full rounded-xl">{loading?'Signing in...':'Sign in'}</Button></div><p className="mt-6 text-center text-xs text-[#809189]">By Signing in you accecpted Terms and Conditions policy</p></form></div></main>;
}

function Metric({ icon: Icon, label, value, note, positive, warning, progress }: { icon: typeof WalletCards; label: string; value: string; note: string; positive?: boolean; warning?: boolean; progress?: number }) { return <div className="rounded-2xl border border-[#dbe5e0] bg-white p-5 shadow-[0_10px_30px_rgba(17,47,36,.03)]"><div className="flex items-center justify-between"><p className="text-xs font-semibold text-[#71847c]">{label}</p><div className={`grid size-9 place-items-center rounded-xl ${warning ? 'bg-[#fff0e9] text-[#c95741]' : 'bg-[#e7f5ed] text-[#237253]'}`}><Icon className="size-4" /></div></div><p className="mt-3 text-[26px] font-bold tracking-[-.035em]">{value}</p>{progress ? <><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-[#eaf0ed]"><div className="h-full rounded-full bg-[#2d8b63]" style={{width: `${progress}%`}} /></div><p className="mt-2 text-[11px] text-[#7d8e87]">{note}</p></> : <p className={`mt-2 text-[11px] ${positive ? 'text-[#25845d]' : warning ? 'text-[#ca6049]' : 'text-[#7d8e87]'}`}>{note}</p>}</div> }
function ProgressRow({name, value, width, color}: {name: string; value: string; width: string; color: string}) { return <div><div className="mb-1.5 flex justify-between text-xs"><span className="text-[#71837c]">{name}</span><span className="font-bold">{value}</span></div><div className="h-1.5 rounded-full bg-[#eef2f0]"><div className="h-full rounded-full" style={{width, backgroundColor: color}} /></div></div> }

function Period({value,onChange}:{value:string;onChange:(v:string)=>void}) { return <div className="flex w-fit rounded-xl border border-[#d7e2dd] bg-white p-1 text-xs font-semibold">{['Today','Week','Month'].map(p=><button key={p} onClick={()=>onChange(p)} className={`rounded-lg px-3 py-2 ${value===p?'bg-[#143b2e] text-white':'text-[#6a7d75]'}`}>{p}</button>)}</div> }

